package com.example.user_service;
import com.example.user_service.repository.CvRepository; import com.example.user_service.service.CvService; import com.example.user_service.storage.ObjectStorage; import org.junit.jupiter.api.Test; import org.springframework.mock.web.MockMultipartFile; import java.io.InputStream; import java.util.concurrent.atomic.AtomicReference; import static org.assertj.core.api.Assertions.*; import static org.mockito.ArgumentMatchers.any; import static org.mockito.Mockito.*;
class CvServiceCompensationTest {@Test void databaseFailureAfterUploadDeletesObject(){CvRepository repo=mock(CvRepository.class);when(repo.saveAndFlush(any())).thenThrow(new RuntimeException("db down"));AtomicReference<String> up=new AtomicReference<>(),del=new AtomicReference<>();ObjectStorage storage=new ObjectStorage(){public void put(String k,InputStream d,long s,String t){up.set(k);}public void delete(String k){del.set(k);}};CvService service=new CvService(repo,storage,1024);var file=new MockMultipartFile("file","cv.pdf","application/pdf","%PDF-valid".getBytes());assertThatThrownBy(()->service.upload(java.util.UUID.randomUUID(),file,false)).isInstanceOf(RuntimeException.class);assertThat(del.get()).isEqualTo(up.get());}}
